import{_ as r,o as a,c as o,aO as d}from"./chunks/framework.BFrk9dwu.js";const i="/travel/luoyang.jpg",n="/travel/luoyang/d1-lijingmen-1.jpg",l="/travel/luoyang/d1-night-1.jpg",e="/travel/luoyang/d2-shilihualang-1.jpg",s="/travel/luoyang/d2-jinding-1.jpg",g="/travel/luoyang/d3-longmen-1.jpg",h="/travel/luoyang/d3-yingtianmen-1.jpg",p="/travel/luoyang/d4-baimasi-1.jpg",v=JSON.parse('{"title":"洛阳：老君山的雪，和十三朝古都","description":"洛阳四天三晚的行程：老城夜市、老君山看雪、龙门石窟和洛阳博物馆、白马寺，附交通、住宿、美食、注意事项与预算","frontmatter":{"title":"洛阳：老君山的雪，和十三朝古都","date":"2026-11-18T04:10:00.000Z","description":"洛阳四天三晚的行程：老城夜市、老君山看雪、龙门石窟和洛阳博物馆、白马寺，附交通、住宿、美食、注意事项与预算","categories":["life","travel"],"permalink":"/pages/bdb566"},"headers":[],"relativePath":"life/travel/luoyang.md","filePath":"life/travel/luoyang.md","lastUpdated":1794902807000}'),c={name:"life/travel/luoyang.md"};function u(f,t,b,m,_,y){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="洛阳-老君山的雪-和十三朝古都" tabindex="-1">洛阳：老君山的雪，和十三朝古都 <a class="header-anchor" href="#洛阳-老君山的雪-和十三朝古都" aria-label="Permalink to &quot;洛阳：老君山的雪，和十三朝古都&quot;">​</a></h1><div class="travel-hero"><img src="'+i+'" alt="雪后的老君山金顶：五座金瓦道观覆着白雪，云海在半山翻涌，晨光打在屋脊上"></div><p>四天三晚：一天给老君山，一天给龙门石窟和博物馆，一天给老城和白马寺。中原的冬天干冷，雪下得干脆；雪后上山，剩下的时间都用来把石头上的朝代看清楚。</p><p>老君山在栾川，离市区一百六十公里，来回一趟基本吃掉一整天，所以最少留三天，不然全程都在路上。</p><h2 id="什么时候去" tabindex="-1">什么时候去 <a class="header-anchor" href="#什么时候去" aria-label="Permalink to &quot;什么时候去&quot;">​</a></h2><ul><li><strong>12 月–次年 2 月</strong>：雪季。老君山雪后一到三天最好看，人少、票价淡季，但真冷——市区白天五六度、夜里零下三四度，山顶零下十度上下还刮风。</li><li><strong>3 月底–4 月</strong>：牡丹花会，全城开花也全城是人，酒店翻倍。</li><li><strong>5–10 月</strong>：天气最舒服，但暑期和节假日挤，老君山索道排队能排两小时。</li></ul><p>想看雪就别犹豫一月，但要接受一个事实：<strong>雪不是天天有，也不是下雪那天最好看</strong>。</p><h2 id="怎么到-城里怎么走" tabindex="-1">怎么到，城里怎么走 <a class="header-anchor" href="#怎么到-城里怎么走" aria-label="Permalink to &quot;怎么到，城里怎么走&quot;">​</a></h2><ul><li><strong>高铁</strong>：洛阳龙门站，站里直接换地铁 2 号线进城，到老城二十来分钟。</li><li><strong>飞机</strong>：洛阳北郊机场航线少，多数人还是走郑州中转。</li><li><strong>市内</strong>：地铁 1、2 号线串起老城、西工、洛龙三个区，市区景点打车起步六七块，都不远。龙门石窟坐 2 号线到八里堂，再打车十分钟。</li><li><strong>去老君山</strong>：洛阳汽车站或龙门客运中心坐去栾川的大巴，在&quot;老君山景区&quot;站下（38 元 / 51 元，全程高速约两小时），下车走三分钟就是票务中心；龙门站还有直达索道口的旅游直通车，三十五到五十块，一个半小时。</li></ul><p>自驾走洛栾高速，一百六十公里，下高速四公里到景区。山路弯多，雪天不建议自己开。</p><h2 id="四天怎么走" tabindex="-1">四天怎么走 <a class="header-anchor" href="#四天怎么走" aria-label="Permalink to &quot;四天怎么走&quot;">​</a></h2><h3 id="day-1-·-落地-去老城吃一顿" tabindex="-1">Day 1 · 落地，去老城吃一顿 <a class="header-anchor" href="#day-1-·-落地-去老城吃一顿" aria-label="Permalink to &quot;Day 1 · 落地，去老城吃一顿&quot;">​</a></h3><p>下午到，先把行李放下。天黑前走到<strong>丽景门</strong>，城门楼亮灯之后最好看，城墙上能一直走到十字街口。</p><div class="travel-grid"><figure><img src="'+n+'" alt="洛阳丽景门夜景：城门楼被暖黄灯光照亮，城下是护城河和垂柳，行人裹着冬衣走过"><figcaption>丽景门：灯亮起来之后，老城才算开门</figcaption></figure><figure><img src="'+l+'" alt="洛阳老城夜市：红灯笼下的小吃摊，铁板上煎着饼和豆腐，热气腾腾"><figcaption>十字街夜市，一路吃过去</figcaption></figure></div><p>穿过丽景门就是<strong>老城十字街</strong>，一条街从头吃到尾：不翻汤、浆面条、锅贴、涮牛肚，摊子上都冒着热气。第一晚别急着找大馆子，小吃街才是洛阳的日常。</p><p>吃完要是还有力气，<strong>洛邑古城</strong>免费，就在附近，晚上灯一亮满街都是拍汉服的人。</p><h3 id="day-2-·-老君山-一整天" tabindex="-1">Day 2 · 老君山，一整天 <a class="header-anchor" href="#day-2-·-老君山-一整天" aria-label="Permalink to &quot;Day 2 · 老君山，一整天&quot;">​</a></h3><p>这一天必须早出晚归，时刻表照着走：</p><table tabindex="0"><thead><tr><th>时间</th><th>干什么</th><th>花费</th></tr></thead><tbody><tr><td>6:20</td><td>从老城打车去汽车站</td><td>15–25 元</td></tr><tr><td>7:00</td><td>大巴到&quot;老君山景区&quot;站，两小时</td><td>38–51 元</td></tr><tr><td>9:10</td><td>景区交通车到索道口（游客中心到索道口七公里，私家车进不去）</td><td>20–30 元</td></tr><tr><td>9:40</td><td>一级索道（中灵或云景二选一）上中天门</td><td>往返 130 元</td></tr><tr><td>10:00</td><td>二级峰林索道到十里画屏入口，省一小时半的爬坡</td><td>往返 80 元</td></tr><tr><td>10:30</td><td><strong>十里画屏</strong>栈道贴着悬崖走，雪后一整条都是白的</td><td>—</td></tr><tr><td>12:00</td><td>马鬃岭、<strong>金顶道观群</strong>，这里就是照片里那五座金殿</td><td>门票 100 元</td></tr><tr><td>13:00</td><td>山顶吃口热的（泡面十五块一桶，自带干粮也行）</td><td>20–60 元</td></tr><tr><td>14:00</td><td>开始下山，<strong>17:30 前必须回到索道站</strong></td><td>—</td></tr><tr><td>17:00</td><td>大巴回洛阳，问好司机末班时间</td><td>38–51 元</td></tr></tbody></table><figure class="travel-photo"><img src="'+e+'" alt="雪后的老君山十里画屏：悬崖栈道覆着白雪，贴着岩壁蜿蜒向前，脚下是深谷云雾"><figcaption>十里画屏：栈道贴着悬崖走，雪把路铺成一条白线</figcaption></figure><figure class="travel-photo"><img src="'+s+'" alt="老君山金顶：覆雪的石阶通向金色殿宇，游客在观景台上看云海"><figcaption>金顶：五座殿，雪一盖就是另一个样子</figcaption></figure><p>山顶比市区低十度，风还大。<strong>防水防滑的鞋或者冰爪</strong>（山下十几块买一副）是这天的关键，雪后栈道看着干净，踩上去是冰。手套、帽子、暖宝宝都带上，山上不单独卖热水，保温杯灌满再上去。</p><h3 id="day-3-·-龙门石窟-然后是博物馆和夜里的城门" tabindex="-1">Day 3 · 龙门石窟，然后是博物馆和夜里的城门 <a class="header-anchor" href="#day-3-·-龙门石窟-然后是博物馆和夜里的城门" aria-label="Permalink to &quot;Day 3 · 龙门石窟，然后是博物馆和夜里的城门&quot;">​</a></h3><p>8 点开门就进<strong>龙门石窟</strong>，从西山石窟走到东山石窟，再过桥看香山寺和白园，三四个小时。卢舍那大佛在伊河西岸的崖壁上，冬天斜光正好打在脸上。</p><figure class="travel-photo"><img src="'+g+'" alt="洛阳龙门石窟：卢舍那大佛坐在灰黄色崖壁上，佛龛层层排列，崖下是伊河"><figcaption>龙门石窟：一尊佛，一整个朝代的脸</figcaption></figure><p>沿河的步道风大，比市区冷一档。中午回城吃饭，下午去<strong>洛阳博物馆</strong>——免费，但要提前预约，<strong>周一闭馆</strong>，唐三彩和河洛文明两个厅别错过。</p><p>天黑之后去<strong>应天门</strong>看灯光，或者买明堂天堂的联票一百二，站在城楼底下才明白&quot;神都&quot;两个字有多重。</p><figure class="travel-photo"><img src="'+h+'" alt="洛阳应天门夜景：唐风城楼整体亮灯，两侧阙楼对称展开，广场上有人影"><figcaption>应天门：晚上亮灯，城门才显出尺度</figcaption></figure><h3 id="day-4-·-白马寺-然后回程" tabindex="-1">Day 4 · 白马寺，然后回程 <a class="header-anchor" href="#day-4-·-白马寺-然后回程" aria-label="Permalink to &quot;Day 4 · 白马寺，然后回程&quot;">​</a></h3><p>上午去<strong>白马寺</strong>，三十五块，中国第一座官办寺院。除了中式院落，后面还有印度、缅甸、泰国的佛殿，风格差得很远，一个院子走完像出了趟国。</p><figure class="travel-photo"><img src="'+p+'" alt="雪后的白马寺：红墙灰瓦的山门覆着薄雪，屋檐挂雪，香炉青烟升起"><figcaption>白马寺：香火和雪一起落下来</figcaption></figure><p>两小时够逛，午饭后回市区拿行李。从老城去龙门站留一小时，别掐点。</p><h2 id="住哪" tabindex="-1">住哪 <a class="header-anchor" href="#住哪" aria-label="Permalink to &quot;住哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>适合</th><th>说明</th></tr></thead><tbody><tr><td>老城区（丽景门、十字街）</td><td>主要住这儿</td><td>夜市步行就到，早上赶汽车站近，去老君山方便</td></tr><tr><td>洛龙区（龙门站一带）</td><td>最后一天赶车</td><td>新区、酒店新，去龙门石窟近，但晚上没什么逛的</td></tr><tr><td>西工区</td><td>想清净</td><td>百货和小吃街多，地铁换乘方便，价格比老城稳</td></tr></tbody></table><p>三四天不用换酒店，住老城最省事。冬天淡季一百五到三百一晚的房间就够好。</p><h2 id="吃什么" tabindex="-1">吃什么 <a class="header-anchor" href="#吃什么" aria-label="Permalink to &quot;吃什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>吃的</th><th>说明</th></tr></thead><tbody><tr><td>洛阳水席</td><td>二十四道菜汤汤水水地上，真不同是老字号，两个人点小席就够</td></tr><tr><td>牛肉汤 / 羊肉汤</td><td>洛阳人的早饭，汤要烫、饼要泡，十块上下管饱</td></tr><tr><td>不翻汤</td><td>绿豆面薄饼下锅不翻，酸辣，夜市里到处都是</td></tr><tr><td>浆面条</td><td>发酵的浆水煮面，酸得很直接，外地人第一次要小碗</td></tr><tr><td>锅贴</td><td>十字街现煎，底面焦脆</td></tr><tr><td>涮牛肚</td><td>一把签子下锅，蘸芝麻酱，夜宵首选</td></tr><tr><td>牡丹饼</td><td>带回家的伴手礼，花会期间满街都是</td></tr></tbody></table><p>吃的集中在这几条街：<strong>老城十字街</strong>（最热闹）、<strong>西工小街</strong>（本地人多）、<strong>民主街</strong>（清静些）。</p><h2 id="需要重点注意的" tabindex="-1">需要重点注意的 <a class="header-anchor" href="#需要重点注意的" aria-label="Permalink to &quot;需要重点注意的&quot;">​</a></h2><ul><li><strong>老君山下午别进山</strong>：冬季索道 15:00 停止上行，赶不上就白跑一天。下山索道 18:30 截止，17:30 前必须回到站里。</li><li><strong>雪天路滑</strong>：栈道有冰，必须防滑鞋或冰爪，一步一步走，别边拍照边走。</li><li><strong>山顶真的很冷</strong>：零下十度加大风，羽绒、帽子、手套、暖宝宝，别按市区的穿法上山。</li><li><strong>龙门石窟冬天没有夜游灯光</strong>（十二月到二月不亮灯），别指望傍晚去看夜景，白天去。</li><li><strong>洛阳博物馆周一路闭馆</strong>，免费但要预约，当天现场约常常没号。</li><li><strong>别信火车站、高速口拉客的车</strong>：说送到索道口，到了还有八公里山路要加钱。认准车站的正规大巴和直通车。</li><li><strong>山顶只有一个亮灯时段</strong>：日落前后十五分钟，看完就天黑了。当天往返基本接不上，想看灯就得住山上，条件很简陋，自己权衡。</li><li><strong>春节前后别去</strong>：人多、价高、索道排队两小时起。</li><li><strong>看雪要看命</strong>：出发前四十八小时查栾川天气，预报雨雪大雾就把老君山和龙门石窟那天对调。</li></ul><h2 id="花费参考-冬季淡季" tabindex="-1">花费参考 | 冬季淡季 <a class="header-anchor" href="#花费参考-冬季淡季" aria-label="Permalink to &quot;花费参考 | 冬季淡季&quot;">​</a></h2><p>四天三晚，不含往返大交通，人均一千四到两千：</p><ul><li><strong>住</strong>：三晚四百五到九百</li><li><strong>门票 + 索道</strong>：老君山三百四到四百（门票淡季常有八十的价）、龙门石窟九十、白马寺三十五、应天门或明堂一百二</li><li><strong>吃</strong>：一天六十到一百</li><li><strong>市内交通</strong>：一百到一百五</li></ul><p><a href="/life/travel/">← 回旅游攻略</a></p>',44)])])}const x=r(c,[["render",u]]);export{v as __pageData,x as default};
